import{_ as i,o as t,a,b as r}from"./app.DKoEZOcr.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程","link":"/guide/operator_practice/simd_operator_impl/vector_programming/vector_programming"},{"text":"概述","link":"/guide/operator_practice/simd_operator_impl/vector_programming/overview"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming/overview.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming/overview.md","lastUpdated":1787050286000}'),l={name:"guide/operator_practice/simd_operator_impl/vector_programming/overview.md"};function o(_,e,c,p,s,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000002500468230"></span></h1><p>本节将以Add算子为例，带您快速构建Ascend C矢量算子程序，并学习矢量算子开发的典型场景以及处理方式。涉及的场景包括：</p><ul><li><a href="basic_vector_operator.html">基础矢量算子</a>：开发一个简单的Add矢量算子。</li><li><a href="tbuf_usage.html">TBuf的使用</a>：在算子计算过程中使用临时空间存储运算的中间结果。</li><li><a href="multi_core_tiling/overview.html">多核Tiling切分</a>：当算子需要多核并行计算或支持动态shape时，对输入数据进行切分、分块计算，并将不同数据块分配到多个AI Core上处理。 <ul><li><a href="multi_core_tiling/main_block_even_split.html">主块均分</a>：算子在AI处理器的多个核上运行，所有核的计算数据量相等且32字节对齐。</li><li><a href="multi_core_tiling/tail_block_even_split.html">尾块均分</a>：算子在AI处理器的多个核上运行，所有核的计算数据量相等，每个核上除最后一个数据块（尾块）外，其余数据块的数据量相等，每个核都需要处理尾块数据的计算。</li><li><a href="multi_core_tiling/tail_core_split.html">尾核切分</a>：算子在AI处理器的多个核上运行，数据无法平均分配到每个核。将所有核分为多个整核和多个尾核，整核的计算数据量相等，尾核的计算数据量相等。</li><li><a href="multi_core_tiling/tail_core_tail_block_split.html">尾核尾块切分</a>：算子在AI处理器的多个核上运行，数据无法平均分配到每个核，同时每个核内的数据无法均分，除最后一个数据块（尾块）外，其余数据块的数据量相等，每个核都需要单独处理尾块数据的计算。</li></ul></li><li><a href="double_buffer_scenario.html">DoubleBuffer场景</a>：开启double buffer，算子中的多条流水并行执行。</li><li><a href="broadcast_scenario.html">Broadcast场景</a>：算子中两个输入的shape（形状）不相等，需要将一个输入的shape进行Broadcast（广播）后，再执行计算。</li><li><a href="unaligned_scenario.html">非对齐场景</a>：更多数据非32字节对齐场景的处理方案。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意 进行数据搬运和Vector计算时，对于搬运的数据长度和操作数的起始地址有如下的对齐要求：</p><ul><li>使用DataCopy接口进行数据搬运，搬运的数据长度和操作数在Unified Buffer（UB）上的起始地址必须保证32字节对齐。</li><li>通常情况下，进行Vector计算时，操作数的起始地址必须保证32字节对齐，执行计算的基本单位为32字节。</li></ul></div></article></div>',1)])])}const u=i(l,[["render",o]]);export{n as __pageData,u as default};
